effect.shader:
float gmHash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
void main(){
  vec2 uv = acScreenNorm;
  float t = floor(acTime * speed);
  float row = floor(uv.y * rows);
  float r1 = gmHash(vec2(row, t));
  float r2 = gmHash(vec2(row * 3.7, t + 5.1));
  float active = step(1.0 - chance, r1);
  uv.x += (r2 - 0.5) * 2.0 * amount * active;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = src.a;
  vec3 c = src.rgb / max(a, 1e-4);
  c = mix(c, c * vec3(1.4, 0.8, 1.2), active * tint);
  gl_FragColor = vec4(clamp(c, 0.0, 1.0) * a, a);
}
